    end
  end

  defp class_name(name) do
    if Config.text?(name, 200),
      do: name,
      else: invalid!("retry non_retryable: a module or a class name")
  end

  defp activity(handler) do
    case Function.info(handler, :type) do
      {:type, :external} ->
        {:module, module} = Function.info(handler, :module)
        {:name, fun} = Function.info(handler, :name)
        %{"activity" => inspect(module) <> "." <> Atom.to_string(fun)}

      _other ->
        %{}
    end
  end

  defp node_name!(wf, name) do
    # A `.` would split the name in a reference (`${steps.a.b}` reads key b of step a), so node names have none.
    unless name?(name) and not String.contains?(name, ".") and
             not String.starts_with?(name, "compensate:"),
           do:
             invalid!(wf, "a node", "the name is not letters, digits, _ - : (nor compensate:...)")

    if MapSet.member?(wf.names, name), do: invalid!(wf, name, "the name is used twice")
    name
  end

  defp known!(wf, name, option, spec, update? \\ false) do
    for step <- Ref.steps(spec), not MapSet.member?(wf.leaves, step) do
      invalid!(wf, name, "#{option} refers to step #{step}, which is not declared before it")
    end

    references = Ref.references(spec)

    if not update? and Enum.any?(references, &update_ref?/1),
      do: invalid!(wf, name, "#{option}: update_input/1 is only for updates")

    references
  end

  defp update_ref?(expr), do: expr == "${update}" or String.starts_with?(expr, "${update.")

  defp put_update(wf, name, handler, opts) do
    Config.check_keys!(opts, [:validate, :message, :input, :result, :timeout_ms])
    where = update_name!(wf, name)
    handler_rules!(wf, where, handler, opts)

    unless opts[:message] == nil or
             (opts[:validate] != nil and Config.text?(opts[:message], 300)),
           do: invalid!(wf, where, "message: a text of at most 300 characters, with validate:")

    spec =
      %{}
      |> optional("handler", handler && true)
      |> optional("validate", opts[:validate] && update_check!(wf, where, opts[:validate]))
      |> optional("message", opts[:message])
      |> optional("input", opts[:input] && update_template!(wf, where, "input", opts[:input]))
      |> optional("result", opts[:result] && update_template!(wf, where, "result", opts[:result]))
      |> optional("timeout_ms", ms!(wf, "#{where}, timeout_ms", opts[:timeout_ms], 1))

    spec = if handler, do: Map.put(spec, :handler, hide(handler)), else: spec
    %{wf | updates: Map.put(wf.updates, name, spec)}
  end

  defp update_name!(wf, name) do
    unless is_binary(name) and Regex.match?(@id, name),
      do: invalid!(wf, "an update", "the name is not letters, digits, _ and -")

    if Map.has_key?(wf.updates, name), do: invalid!(wf, "update #{name}", "is declared twice")

    if map_size(wf.updates) >= 50,
      do: invalid!(wf, "update #{name}", "a workflow has at most 50 updates")

    "update #{name}"
  end

  defp handler_rules!(wf, where, nil, opts) do
    unless opts[:input] == nil and opts[:timeout_ms] == nil,
      do: invalid!(wf, where, "input: and timeout_ms: are for an update with a handler")
  end

  defp handler_rules!(wf, where, handler, opts) do
    unless is_function(handler, 2),
      do: invalid!(wf, where, "the handler must be a 2-arity function")

    if opts[:result] != nil, do: invalid!(wf, where, "result: is for an update without a handler")
  end

  defp update_check!(wf, where, %Ref{} = ref), do: hd(update_refs!(wf, where, "validate", ref))
  defp update_check!(wf, where, _other), do: invalid!(wf, where, "validate: must be a reference")

  defp update_template!(wf, where, option, spec) do
    update_refs!(wf, where, option, spec)
    checked_template!(wf, where, spec, option, true)
  end

  @update ["${update.name}", "${update.id}", "${update.input}"]

  defp update_refs!(wf, where, option, spec) do
    references = known!(wf, where, option, spec, true)

    for ref <- references,
        update_ref?(ref),
        ref not in @update and not String.starts_with?(ref, "${update.input.") do
      invalid!(
        wf,
        where,
        "#{option} reads the update only through update_input/1 and the paths update.name and update.id"
      )
    end

    references
  end

  defp optional(map, _key, nil), do: map
  defp optional(map, key, value), do: Map.put(map, key, value)

  defp count!(_wf, _key, nil, _min, _max), do: nil

  defp count!(_wf, _key, value, min, max)
       when is_integer(value) and value >= min and value <= max,
       do: value

  defp count!(wf, key, _value, min, max),
    do: invalid!(wf, "continue_as_new", "#{key}: an integer #{min}..#{max}")

  # An update's references to other updates (`${updates.<name>...}`) name updates of this workflow, which may be
  # declared after it: checked once the workflow is complete.
  defp known_updates!(wf) do
    for {name, spec} <- wf.updates,
        "${updates." <> rest <- strings(Map.take(spec, ["validate", "input", "result"])) do
      other = rest |> String.trim_trailing("}") |> String.split(".") |> hd()

      unless Map.has_key?(wf.updates, other),
        do: invalid!(wf, "update #{name}", "refers to update #{other}, not declared")
    end
  end

  defp strings(text) when is_binary(text), do: [text]
  defp strings(map) when is_map(map), do: map |> Map.values() |> Enum.flat_map(&strings/1)
  defp strings(list) when is_list(list), do: Enum.flat_map(list, &strings/1)

  defp capped!(references, wf, name, option) do
    if length(references) > 64, do: invalid!(wf, name, "#{option} makes more than 64 references")
    references
  end

  defp checked_template!(wf, name, spec, option \\ "input", update? \\ false) do
    known!(wf, name, option, spec, update?)
    template!(wf, "#{name}, #{option}", spec, update?)
  end

  # A template the engine resolves: references in maps (name keys) and lists, nothing literal.
  defp template!(wf, where, spec, update?), do: walk!(wf, where, spec, update?, 1)

  defp walk!(wf, where, _spec, _update?, depth) when depth > 8,
    do: invalid!(wf, where, "nests deeper than 8 levels")

  defp walk!(wf, where, %Ref{expr: expr}, update?, _depth) do
    if not update? and update_ref?(expr),
      do: invalid!(wf, where, "update_input/1 is only for updates")

    expr
  end

  defp walk!(wf, where, map, update?, depth) when is_map(map) and not is_struct(map) do
    if map_size(map) > 100, do: invalid!(wf, where, "has more than 100 keys")

    for {key, value} <- Enum.sort_by(map, &key_name(wf, where, elem(&1, 0))), reduce: %{} do
      acc ->
        key = key_name(wf, where, key)

        if Map.has_key?(acc, key),
          do: invalid!(wf, where, "has a key twice (as an atom and a string)")

        Map.put(acc, key, walk!(wf, "#{where}.#{key}", value, update?, depth + 1))
    end
  end

  defp walk!(wf, where, list, update?, depth) when is_list(list) do
    unless Config.proper_list?(list) and length(list) <= 100,
      do: invalid!(wf, where, "a list of at most 100 items")

    Enum.map(list, &walk!(wf, where, &1, update?, depth + 1))
  end

  defp walk!(wf, where, _literal, _update?, _depth),
    do:
      invalid!(
        wf,
        where,
        "must be references (input, output, ref) in maps and lists: literal values are not sent"
      )

  defp key_name(wf, where, key) do
    key = if is_atom(key) and key not in [nil, true, false], do: Atom.to_string(key), else: key
    if name?(key), do: key, else: invalid!(wf, where, "has a key that is not a name")
  end

  defp name?(name), do: is_binary(name) and Regex.match?(@name, name)

  defp ms!(_wf, _option, nil, _min), do: nil
  defp ms!(_wf, _option, ms, min) when is_integer(ms) and ms >= min and ms <= @year, do: ms

  defp ms!(wf, option, _ms, min),
    do: invalid!(wf, option, "milliseconds, an integer #{min}..#{@year}")

  @spec invalid!(t(), String.t(), String.t()) :: no_return()
  defp invalid!(wf, where, message), do: invalid!("workflow #{wf.name}, #{where}: #{message}")
  @spec invalid!(String.t()) :: no_return()
  defp invalid!(message), do: raise(ArgumentError, "JoobQ workflow: " <> message)
end
